-- DGVC LMS — demo PYQ resources table, storage bucket and RLS.
-- Pairs with supabase/seed/pyq_resources.sql (auto-generated by scripts/pyq/generate_pyq_papers.py).
-- NOTE: written for the demo; not yet executed against a live Supabase project. Review before applying.

create extension if not exists pgcrypto;

-- Minimal profiles table for role checks (the full LMS schema extends this).
create table if not exists public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  full_name text not null,
  role text not null default 'student' check (role in ('student', 'faculty', 'department_admin', 'super_admin')),
  department text,
  approval_status text not null default 'pending' check (approval_status in ('pending', 'approved', 'rejected', 'suspended')),
  assigned_subjects text[] not null default '{}',
  created_at timestamptz not null default now()
);
alter table public.profiles enable row level security;
create policy "read own profile" on public.profiles for select using (id = auth.uid());
-- No update policy for students: role and approval_status can only be changed by the service role / admin functions.

create table if not exists public.pyq_demo_resources (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  description text not null default '',
  subject text not null,
  subject_code text not null,
  department text not null,
  programme text not null,
  semester smallint not null check (semester between 1 and 8),
  exam_year smallint not null check (exam_year between 2000 and 2100),
  exam_month text not null,
  exam_type text not null,
  exam_date date,
  max_marks smallint not null,
  sections jsonb not null default '[]',
  file_url text not null,                  -- public/demo-pdfs path or storage object path
  file_size integer not null,
  page_count smallint not null,
  resource_type text not null default 'question_paper' check (resource_type = 'question_paper'),
  status text not null default 'draft' check (status in ('draft', 'published', 'unpublished', 'archived')),
  demo_label text not null default 'SAMPLE / AI-GENERATED DEMO QUESTION PAPER',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);
create index if not exists pyq_demo_status_idx on public.pyq_demo_resources (status) where deleted_at is null;
create index if not exists pyq_demo_filter_idx on public.pyq_demo_resources (subject_code, semester, exam_year);

-- Helpers evaluated server-side; never trust a role sent by the client.
create or replace function public.current_profile() returns public.profiles
language sql stable security definer set search_path = public as $$
  select * from public.profiles where id = auth.uid()
$$;

create or replace function public.can_manage_pyq(r public.pyq_demo_resources) returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((
    select case p.role
      when 'super_admin' then true
      when 'department_admin' then p.department = r.department
      when 'faculty' then r.subject_code = any (p.assigned_subjects)
      else false end
    from public.profiles p where p.id = auth.uid() and p.approval_status = 'approved'
  ), false)
$$;

alter table public.pyq_demo_resources enable row level security;

create policy "approved students read published papers" on public.pyq_demo_resources
  for select using (
    deleted_at is null and (
      (status = 'published' and (public.current_profile()).approval_status = 'approved')
      or public.can_manage_pyq(pyq_demo_resources)
    )
  );
create policy "staff update papers in scope" on public.pyq_demo_resources
  for update using (public.can_manage_pyq(pyq_demo_resources)) with check (public.can_manage_pyq(pyq_demo_resources));
create policy "staff insert papers in scope" on public.pyq_demo_resources
  for insert with check (public.can_manage_pyq(pyq_demo_resources));
create policy "staff delete papers in scope" on public.pyq_demo_resources
  for delete using (public.can_manage_pyq(pyq_demo_resources));

-- Private bucket for the PDFs. Students get files through signed URLs only for papers they can see.
insert into storage.buckets (id, name, public) values ('demo-pdfs', 'demo-pdfs', false)
on conflict (id) do nothing;

create policy "read pdfs of visible papers" on storage.objects for select using (
  bucket_id = 'demo-pdfs' and exists (
    select 1 from public.pyq_demo_resources r
    where r.file_url = '/demo-pdfs/' || storage.objects.name   -- RLS on the table applies inside this subquery
  )
);
create policy "staff upload pdfs" on storage.objects for insert with check (
  bucket_id = 'demo-pdfs' and (public.current_profile()).role in ('faculty', 'department_admin', 'super_admin')
);
